import React from "react";
import { createRoot } from "react-dom/client";
import { PuzzleComponent } from "./PuzzleComponent";

const elem = document.getElementById("puzzle-root");
if (elem) {
  const gridsList = (window as unknown as { gridsList: string[][][][] })
    .gridsList;
  const dialogList = (window as unknown as { dialogList: string[][] })
    .dialogList;
  const root = createRoot(elem);
  root.render(
    <PuzzleComponent gridsList={gridsList} dialogList={dialogList} />,
  );
} else {
  console.error(
    "Could not mount App because #puzzle-root was nowhere to be found",
  );
}
