const BananagramsTile = ({
  letter,
  randomSeed,
}: {
  letter: string;
  randomSeed: number;
}) => {
  if (letter === " ") {
    return <div className={TILE_SIZE} />;
  }
  return (
    <div
      className={`${TILE_SIZE} bg-amber-100 border border-gray-200 rounded-sm flex items-center justify-center ${TILE_FONT_SIZE} font-semibold text-black`}
      style={{
        // Tiny jitter: translate up to ±1.5px, rotate up to ±1.5deg
        transform: `translate(${
          RANDOM_JITTERS_X[randomSeed % RANDOM_JITTERS_X.length]
        }px, ${
          RANDOM_JITTERS_Y[randomSeed % RANDOM_JITTERS_Y.length]
        }px) rotate(${
          RANDOM_ROTATIONS[randomSeed % RANDOM_ROTATIONS.length]
        }deg)`,
        fontFamily:
          "'Roboto Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace",
      }}
    >
      {letter}
    </div>
  );
};

const BananagramsGrid = ({
  grid,
  position,
}: {
  grid: string[][];
  position: { color: string; x: number; y: number; rotation: number };
}) => {
  const { color, x, y, rotation } = position;
  return (
    <div
      key={color}
      className="absolute"
      style={{
        left: x - 100, // center grid (assuming grid is 200x200)
        top: y - 100,
        width: 200,
        height: 200,
        pointerEvents: "none", // pass through so user can't drag/select
        // Center at x,y, then rotate about its center
        transform: `rotate(${rotation}deg)`,
        transformOrigin: "100px 100px", // rotate about center of grid
      }}
    >
      <div className="w-fit items-center justify-center">
        <table className="text-sm">
          <tbody>
            {grid.map((row, rowidx) => (
              <tr key={rowidx}>
                {row.map((cell, cellidx) => (
                  <td className="text-center p-0" key={cellidx}>
                    <BananagramsTile
                      letter={cell}
                      randomSeed={cellidx + rowidx}
                    />
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const sectorAngles = [0, 60, 120, 180, 240, 300];

